import random
import string
from typing import List

# This generator produces valid-ish ASN.1 specifications as text bytes.
# It focuses on creating compilable modules with various constructs so that
# asn1_parser2tree/asn1_parser2array receive interesting, valid inputs.

_MAX_BYTES = 4096

OID_ARCS = [
    "0", "1", "2"
]

TYPES_PRIMITIVE = [
    "INTEGER",
    "BOOLEAN",
    "OCTET STRING",
    "BIT STRING",
    "NULL",
    "OBJECT IDENTIFIER",
    "UTCTime",
    "GeneralizedTime",
    "IA5String",
    "PrintableString",
    "UTF8String",
]

# Common useful constraints
CONSTRAINTS = [
    "(SIZE(0..255))",
    "(0..255)",
    "(1..MAX)",
    "(SIZE(1..64))",
]

TAG_CLASSES = [
    ("UNIVERSAL", None),
    ("APPLICATION", None),
    ("PRIVATE", None),
    ("CONTEXT", "[{}]"),  # handled separately
]

PRINT_MODES = [
    "-- Simple comment line\n",
    "-- Another note\n",
]

def _rand_ident(r: random.Random, prefix: str = "T") -> str:
    first = r.choice(string.ascii_letters + "_")
    rest = ''.join(r.choice(string.ascii_letters + string.digits + "_-") for _ in range(r.randint(2, 10)))
    ident = first + rest
    # ASN.1 identifiers typically do not contain '-', but many real specs do; keep but also fallback
    if ident[0].isdigit():
        ident = prefix + ident
    return ident


def _rand_oid(r: random.Random) -> str:
    # Basic dotted decimal OID, with valid first arc 0..2 and second arc per rules
    first = int(r.choice(OID_ARCS))
    if first == 0:
        second = r.randint(0, 39)
    elif first == 1:
        second = r.randint(0, 39)
    else:
        second = r.randint(0, 200)
    arcs = [str(first), str(second)]
    for _ in range(r.randint(1, 6)):
        arcs.append(str(r.randint(0, 2000)))
    return '.'.join(arcs)


def _maybe_constraint(r: random.Random) -> str:
    if r.random() < 0.5:
        return ''
    return ' ' + r.choice(CONSTRAINTS)


def _maybe_default(r: random.Random, base_type: str) -> str:
    if r.random() < 0.6:
        return ''
    if base_type == "INTEGER":
        return " DEFAULT " + str(r.randint(0, 100))
    if base_type == "BOOLEAN":
        return " DEFAULT " + ("TRUE" if r.random() < 0.5 else "FALSE")
    if base_type in ("IA5String", "PrintableString", "UTF8String", "OCTET STRING"):
        s = ''.join(r.choice(string.ascii_letters) for _ in range(r.randint(0, 6)))
        return " DEFAULT '" + s + "'" + ("IA5" if base_type == "IA5String" else ("UTF8" if base_type == "UTF8String" else ""))
    return ''


def _field_decl(r: random.Random) -> str:
    base = r.choice(TYPES_PRIMITIVE)
    text = base + _maybe_constraint(r)
    # Optional tagging
    if r.random() < 0.35:
        tag_no = r.randint(0, 31)
        text = "[{}] {}".format(tag_no, text)
        if r.random() < 0.5:
            text = text + " EXPLICIT"
        elif r.random() < 0.5:
            text = text + " IMPLICIT"
    # OPTIONAL
    opt = " OPTIONAL" if r.random() < 0.5 else ""
    # DEFAULT
    default = '' if opt else _maybe_default(r, base)
    return text + default + opt


def _sequence_type(r: random.Random) -> str:
    n = r.randint(1, 6)
    lines = []
    for _ in range(n):
        name = _rand_ident(r, "f").replace('-', '_')
        lines.append("    {} {}".format(name, _field_decl(r)))
    # Add CHOICE inside occasionally
    if r.random() < 0.4:
        chn = r.randint(2, 4)
        chlines = []
        for _ in range(chn):
            chname = _rand_ident(r, "c").replace('-', '_')
            chlines.append("        {} {}".format(chname, _field_decl(r)))
        lines.append("    alt CHOICE {\n" + ",\n".join(chlines) + "\n    }")
    return "SEQUENCE {\n" + ",\n".join(lines) + "\n}"


def _set_type(r: random.Random) -> str:
    n = r.randint(1, 5)
    lines = []
    for _ in range(n):
        name = _rand_ident(r, "s").replace('-', '_')
        lines.append("    {} {}".format(name, _field_decl(r)))
    return "SET {\n" + ",\n".join(lines) + "\n}"


def _sequence_of_type(r: random.Random) -> str:
    base = r.choice(TYPES_PRIMITIVE)
    return "SEQUENCE OF {}{}".format(base, _maybe_constraint(r))


def _choice_type(r: random.Random) -> str:
    n = r.randint(2, 5)
    lines = []
    for _ in range(n):
        name = _rand_ident(r, "u").replace('-', '_')
        lines.append("    {} {}".format(name, _field_decl(r)))
    return "CHOICE {\n" + ",\n".join(lines) + "\n}"


def _type_assignment(r: random.Random, tname: str) -> str:
    kind = r.random()
    if kind < 0.35:
        rhs = _sequence_type(r)
    elif kind < 0.55:
        rhs = _set_type(r)
    elif kind < 0.75:
        rhs = _sequence_of_type(r)
    else:
        rhs = _choice_type(r)
    return f"{tname} ::= {rhs}\n"


def _value_assignment(r: random.Random, vname: str) -> str:
    # Create various value assignments (INTEGER, OID, BOOLEAN, NULL, STRING)
    choice = r.random()
    if choice < 0.25:
        return f"{vname} INTEGER ::= {r.randint(0, 10000)}\n"
    elif choice < 0.45:
        return f"{vname} OBJECT IDENTIFIER ::= {{{_rand_oid(r)}}}\n"
    elif choice < 0.65:
        return f"{vname} BOOLEAN ::= {'TRUE' if r.random()<0.5 else 'FALSE'}\n"
    elif choice < 0.8:
        return f"{vname} NULL ::= NULL\n"
    else:
        s = ''.join(r.choice(string.ascii_letters) for _ in range(r.randint(1, 10)))
        return f"{vname} IA5String ::= '{s}'\n"


def _exports_imports(r: random.Random, module_name: str, other_module: str) -> str:
    parts = []
    if r.random() < 0.6:
        # EXPORTS
        n = r.randint(1, 4)
        ids = [_rand_ident(r, "E").replace('-', '_') for _ in range(n)]
        parts.append("EXPORTS " + ", ".join(ids) + ";\n")
    if r.random() < 0.5:
        # IMPORTS from other_module
        n = r.randint(1, 3)
        ids = [_rand_ident(r, "I").replace('-', '_') for _ in range(n)]
        parts.append("IMPORTS " + ", ".join(ids) + f" FROM {other_module};\n")
    return ''.join(parts)


def _module_header(r: random.Random, name: str) -> str:
    # Include an OID for the module identity
    oid = _rand_oid(r)
    # Random tag default
    tagdefault = r.choice(["EXPLICIT TAGS", "IMPLICIT TAGS", "AUTOMATIC TAGS"])
    return f"{name} DEFINITIONS {tagdefault} ::= BEGIN\n-- Module OID\n{_rand_ident(r,'moduleOID')} OBJECT IDENTIFIER ::= {{{oid}}}\n"


def _module_footer() -> str:
    return "END\n"


def _build_module(r: random.Random, name: str, other_module: str) -> str:
    content = []
    content.append(_module_header(r, name))
    content.append(_exports_imports(r, name, other_module))

    # A handful of type assignments
    for _ in range(r.randint(3, 8)):
        tname = _rand_ident(r, "T").replace('-', '_')
        content.append(_type_assignment(r, tname))

    # Value assignments (constants), including OIDs
    for _ in range(r.randint(2, 6)):
        vname = _rand_ident(r, "V").replace('-', '_')
        content.append(_value_assignment(r, vname))

    # Define a useful, simple structure pair to encourage create/encode
    base_t = _rand_ident(r, "Base").replace('-', '_')
    content.append(f"{base_t} ::= SEQUENCE {{\n    id OBJECT IDENTIFIER,\n    payload OCTET STRING (SIZE(0..1024)) OPTIONAL,\n    flag BOOLEAN DEFAULT FALSE\n}}\n")

    # Add a nested choice referencing earlier type for cross-links
    ref_t = _rand_ident(r, "Ref").replace('-', '_')
    content.append(f"{ref_t} ::= CHOICE {{\n    item {base_t},\n    many SEQUENCE OF {base_t}\n}}\n")

    content.append(_module_footer())
    return ''.join(content)


def _wrap_multi_modules(r: random.Random, modules: List[str]) -> str:
    # Concatenate modules; many parsers allow multiple modules per file
    inter = "\n\n" + r.choice(PRINT_MODES) + "\n"
    return inter.join(modules)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Build 1-3 modules with cross-imports and varied constructs
    module_count = r.randint(1, 2)
    modules = []
    names = [(_rand_ident(r, "M").replace('-', '_')).upper() for _ in range(module_count)]
    if len(names) == 1:
        other = (names[0] + "_AUX")
        modules.append(_build_module(r, names[0], other))
        # Also add a small auxiliary module occasionally
        if r.random() < 0.7:
            modules.append(_build_module(r, other, names[0]))
    else:
        modules = [_build_module(r, names[i], names[(i+1) % len(names)]) for i in range(len(names))]

    text = _wrap_multi_modules(r, modules)

    # Ensure size limit
    data = text.encode('utf-8', errors='strict')
    if len(data) > _MAX_BYTES:
        data = data[:_MAX_BYTES]
    return data

import random
from typing import List

# This generator produces valid BER/DER TLV byte sequences, focusing on simple
# primitive types commonly handled by libtasn1 low-level helpers:
# - INTEGER
# - OCTET STRING
# - BIT STRING
# - NULL
# - OBJECT IDENTIFIER
# It can also wrap items in constructed SEQUENCE/SET and optionally use
# short/long-form lengths. It avoids indefinite lengths to remain valid for
# DER as well, but still valid BER.
# The resulting buffer is <= 4096 bytes.

# ASN.1 universal tags (low-tag-number form)
TAG_BOOL = 0x01
TAG_INTEGER = 0x02
TAG_BIT_STRING = 0x03
TAG_OCTET_STRING = 0x04
TAG_NULL = 0x05
TAG_OBJECT_ID = 0x06
TAG_SEQUENCE = 0x10  # constructed bit added later
TAG_SET = 0x11       # constructed bit added later

CLS_UNIVERSAL = 0x00
CLS_APPLICATION = 0x40
CLS_CONTEXT = 0x80
CLS_PRIVATE = 0xC0

CONSTRUCTED = 0x20

MAX_TOTAL = 4096


def _enc_len(n: int) -> bytes:
    # DER/BER definite length
    if n < 0x80:
        return bytes([n])
    # long form
    out = []
    tmp = n
    while tmp > 0:
        out.append(tmp & 0xFF)
        tmp >>= 8
    out.reverse()
    return bytes([0x80 | len(out)]) + bytes(out)


def _tlv(tag: int, payload: bytes, cls: int = CLS_UNIVERSAL, constructed: bool = False, high_tag: int = None) -> bytes:
    # Build identifier octets (limit to low-tag-number form for simplicity)
    if high_tag is not None:
        # Encode high-tag-number form when requested
        first = cls | (CONSTRUCTED if constructed else 0) | 0x1F
        # base-128 encode high_tag with continuation bits
        n = high_tag
        base128 = []
        if n == 0:
            base128 = [0]
        else:
            while n > 0:
                base128.append(n & 0x7F)
                n >>= 7
            base128.reverse()
        for i in range(len(base128) - 1):
            base128[i] |= 0x80
        ident = bytes([first] + base128)
    else:
        ident = bytes([cls | (CONSTRUCTED if constructed else 0) | (tag & 0x1F)])
    return ident + _enc_len(len(payload)) + payload


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _encode_integer(rng: random.Random) -> bytes:
    # Generate random signed integer in two's-complement minimal encoding
    # Pick a size 1..16 bytes
    size = rng.randint(1, 16)
    # Bias to interesting patterns
    choices = [0, 1, -1, 127, 128, 255, 256, -128, -129, 2**31-1, -2**31]
    if rng.random() < 0.5:
        val = rng.choice(choices)
    else:
        val = rng.randint(-2**(8*size-1), 2**(8*size-1)-1)
    # Encode to two's complement minimal
    if val >= 0:
        payload = val.to_bytes((val.bit_length() + 7)//8 or 1, 'big', signed=False)
        # Ensure highest bit not set; if set, add leading 0x00
        if payload[0] & 0x80:
            payload = b"\x00" + payload
    else:
        # negative: use signed=True size minimal
        bits = val.bit_length()  # for negative numbers in Python, bit_length ignores sign
        # choose minimal bytes to represent with sign
        for nbytes in range(1, 17):
            try:
                payload = val.to_bytes(nbytes, 'big', signed=True)
                # minimality: ensure top 9 bits are not redundant
                # We'll trim leading 0xFF if next byte has 0x80 set, or 0x00 if not needed
                while len(payload) > 1:
                    if payload[0] == 0xFF and (payload[1] & 0x80):
                        payload = payload[1:]
                    elif payload[0] == 0x00 and not (payload[1] & 0x80):
                        payload = payload[1:]
                    else:
                        break
                break
            except OverflowError:
                continue
    return _tlv(TAG_INTEGER, payload)


def _encode_null() -> bytes:
    return _tlv(TAG_NULL, b"")


def _encode_octet_string(rng: random.Random) -> bytes:
    # Small random payload up to, say, 64 bytes
    length = rng.randint(0, 64)
    payload = _rand_bytes(rng, length)
    return _tlv(TAG_OCTET_STRING, payload)


def _encode_bit_string(rng: random.Random) -> bytes:
    # BIT STRING: first octet is number of unused bits in last byte (0..7)
    bit_len = rng.randint(0, 256)
    byte_len = (bit_len + 7) // 8
    unused = (8 - (bit_len % 8)) % 8
    bits = _rand_bytes(rng, byte_len) if byte_len > 0 else b""
    if byte_len > 0 and unused:
        # zero out the unused bits in the last byte to keep it canonical
        last = bits[-1]
        last &= (0xFF << unused) & 0xFF
        bits = bits[:-1] + bytes([last])
    payload = bytes([unused]) + bits
    return _tlv(TAG_BIT_STRING, payload)


def _encode_oid(rng: random.Random) -> bytes:
    # Generate dotted OID string then encode to DER content octets
    # First two components: 0..2 and 0..(39 if first<2 else arbitrary)
    first = rng.randint(0, 2)
    second = rng.randint(0, 39) if first < 2 else rng.randint(0, 80)
    arcs = [first, second]
    # Add 1..6 more arcs
    for _ in range(rng.randint(1, 6)):
        # bias to interesting sizes
        if rng.random() < 0.3:
            arcs.append(rng.choice([0, 1, 2, 3, 40, 127, 128, 255, 16384]))
        else:
            arcs.append(rng.randint(0, 10000))
    # Convert to DER base-128 content
    first_byte = 40 * arcs[0] + arcs[1]
    content = [first_byte]
    for a in arcs[2:]:
        # base-128 big-endian with continuation bits
        if a == 0:
            content.append(0)
        else:
            tmp = []
            v = a
            while v > 0:
                tmp.append(v & 0x7F)
                v >>= 7
            tmp.reverse()
            for i in range(len(tmp) - 1):
                tmp[i] |= 0x80
            content.extend(tmp)
    return _tlv(TAG_OBJECT_ID, bytes(content))


def _encode_boolean(rng: random.Random) -> bytes:
    # DER: any non-zero is TRUE, but canonical TRUE is 0xFF; FALSE is 0x00
    val = 0xFF if rng.random() < 0.5 else 0x00
    return _tlv(TAG_BOOL, bytes([val]))


def _wrap_constructed(rng: random.Random, items: List[bytes]) -> bytes:
    body = b"".join(items)
    tag = TAG_SEQUENCE if rng.random() < 0.5 else TAG_SET
    return _tlv(tag, body, constructed=True)


def _maybe_context_wrap(rng: random.Random, inner: bytes) -> bytes:
    # Optionally wrap in a context-specific [n] constructed tag
    if rng.random() < 0.2:
        n = rng.randint(0, 15)
        # Use low-tag-number form
        ident = bytes([CLS_CONTEXT | CONSTRUCTED | (n & 0x1F)])
        return ident + _enc_len(len(inner)) + inner
    return inner


def _build_sequence(rng: random.Random, budget: int) -> bytes:
    # Build a sequence/set with random number of fields within budget
    items = []
    while True:
        if len(items) >= 8:
            break
        if sum(len(x) for x in items) > budget:
            break
        choice = rng.random()
        if choice < 0.2:
            item = _encode_null()
        elif choice < 0.4:
            item = _encode_integer(rng)
        elif choice < 0.6:
            item = _encode_octet_string(rng)
        elif choice < 0.75:
            item = _encode_bit_string(rng)
        elif choice < 0.9:
            item = _encode_oid(rng)
        else:
            item = _encode_boolean(rng)
        # Maybe context wrap some items
        if rng.random() < 0.15:
            item = _maybe_context_wrap(rng, item)
        if sum(len(x) for x in items) + len(item) > budget:
            break
        items.append(item)
        if rng.random() < 0.2:
            break
    return _wrap_constructed(rng, items)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide top-level shape: a single primitive or a constructed TLV possibly nested
    pieces: List[bytes] = []

    target_size = rng.randint(16, min(1024, MAX_TOTAL))

    while sum(len(p) for p in pieces) < target_size:
        x = rng.random()
        if x < 0.18:
            tlv = _encode_integer(rng)
        elif x < 0.36:
            tlv = _encode_octet_string(rng)
        elif x < 0.50:
            tlv = _encode_bit_string(rng)
        elif x < 0.62:
            tlv = _encode_null()
        elif x < 0.76:
            tlv = _encode_oid(rng)
        elif x < 0.88:
            tlv = _encode_boolean(rng)
        else:
            # constructed with a budget chunk
            budget = rng.randint(16, 256)
            tlv = _build_sequence(rng, budget)
        # Occasionally use high-tag-number universal (rare but valid) for OCTET STRING clone
        if rng.random() < 0.05:
            # re-wrap payload with high-tag-number for an application-specific constructed container
            payload = tlv
            high_tag = rng.randint(31, 2000)
            tlv = _tlv(0, payload, cls=CLS_APPLICATION, constructed=True, high_tag=high_tag)
        pieces.append(tlv)
        if rng.random() < 0.15:
            break

    blob = b"".join(pieces)
    # Ensure size constraints for the fuzz harness (<= 1024 in stubs, but cap overall <= 4096)
    if len(blob) > 1024:
        blob = blob[:1024]
    return blob

import random
import string
from typing import List

# Target: semantic version string for asn1_check_version(req_version)
# FUZZ_PARAM_STR will be fed by our returned bytes. The harness decides whether to pass
# NULL or our string based on size parity. We generate diverse, valid version-like strings
# of varying lengths to exercise comparison logic and edge handling, while keeping them valid.

SEMVER_NUMS = [
    # Common versions
    "0.9.0", "1.0.0", "1.0", "1.1.1", "2.0.0", "3.0.0",
    # libtasn1 notable versions (historical examples)
    "2.10", "3.4", "4.13", "4.16.0", "4.19.0",
]

PRE_RELEASE_TAGS = ["alpha", "beta", "rc", "pre", "snapshot"]
BUILD_TAGS = ["build", "exp", "dev", "meta"]


def _randint(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _choose(rng: random.Random, arr: List[str]) -> str:
    return arr[_randint(rng, 0, len(arr) - 1)]


def _numeric_component(rng: random.Random, allow_leading_zeros: bool) -> str:
    # Produce a non-negative integer component, possibly with leading zeros to test parsing.
    if allow_leading_zeros and rng.random() < 0.3:
        width = _randint(rng, 1, 4)
        val = _randint(rng, 0, 9999)
        return f"{val:0{width}d}"
    else:
        # Keep numbers relatively small to remain realistic
        return str(_randint(rng, 0, 65535))


def _gen_core_version(rng: random.Random) -> str:
    # Generate common N.N or N.N.N or more components (valid for many version comparisons)
    parts = []
    n_parts = _randint(rng, 2, 4)  # 2-4 numeric components
    for i in range(n_parts):
        parts.append(_numeric_component(rng, allow_leading_zeros=True))
    return ".".join(parts)


def _gen_prerelease(rng: random.Random) -> str:
    # Generate a semver-like prerelease: tag[.num]
    tag = _choose(rng, PRE_RELEASE_TAGS)
    if rng.random() < 0.7:
        # Possibly add numeric identifier(s)
        nums = [str(_randint(rng, 0, 9)) for _ in range(_randint(rng, 1, 3))]
        return tag + "." + ".".join(nums)
    return tag


def _gen_build(rng: random.Random) -> str:
    tag = _choose(rng, BUILD_TAGS)
    if rng.random() < 0.6:
        suffix = ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(_randint(rng, 1, 6)))
        return tag + "." + suffix
    return tag


def _maybe_prefix_v(rng: random.Random) -> str:
    # Some tools accept a leading 'v'
    return "v" if rng.random() < 0.3 else ""


def _gen_version(rng: random.Random) -> str:
    # Choose among curated known versions, or synthesize a rich semver-like string
    mode = rng.random()
    if mode < 0.25:
        ver = _choose(rng, SEMVER_NUMS)
    else:
        ver = _gen_core_version(rng)
    # Optional prerelease and build metadata
    if rng.random() < 0.5:
        ver = ver + "-" + _gen_prerelease(rng)
    if rng.random() < 0.4:
        ver = ver + "+" + _gen_build(rng)
    return _maybe_prefix_v(rng) + ver


def _gen_edge_case(rng: random.Random) -> str:
    # Some edge but still valid-ish inputs: empty string, whitespace-trimmed numbers, long components
    choice = _randint(rng, 0, 6)
    if choice == 0:
        return ""  # empty -> may be treated as incompatible
    if choice == 1:
        return "0"
    if choice == 2:
        return "1"  # single number
    if choice == 3:
        # Many components
        parts = [str(_randint(rng, 0, 9)) for _ in range(_randint(rng, 5, 10))]
        return ".".join(parts)
    if choice == 4:
        # Very large component but numeric
        return f"{_randint(rng, 0, 9)}.{_randint(rng, 0, 9)}.{_randint(rng, 1_000_000, 50_000_000)}"
    if choice == 5:
        # Leading/trailing spaces (still a valid C-string; lib may trim or reject)
        return " " + _gen_core_version(rng) + " "
    # Explicit exact match use-case: major.minor
    return f"{_randint(rng, 0, 10)}.{_randint(rng, 0, 99)}"


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide between standard version and edge cases
    if rng.random() < 0.75:
        s = _gen_version(rng)
    else:
        s = _gen_edge_case(rng)

    # Ensure total size stays reasonable; truncate gracefully if needed.
    # Keep within 512 bytes (well below the 4096-byte cap)
    s = s[:512]

    # Return as bytes (UTF-8). FUZZ_PARAM_STR reads arbitrary bytes as a string; restrict to ASCII
    # characters to stay within typical version string expectations.
    return s.encode('ascii', errors='ignore')
